def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from itertools import combinations

    def apply_absorption(expr1, expr2):
        if expr1 == f"{expr2} & ({expr2} | B)" or expr1 == f"({expr2} | B) & {expr2}":
            return expr2
        if expr1 == f"{expr2} | ({expr2} & B)" or expr1 == f"({expr2} & B) | {expr2}":
            return expr2
        if expr1 == f"{expr2} & (~{expr2} | B)":
            return f"{expr2} & B"
        if expr1 == f"({expr2} & B) | ~{expr2}":
            return f"{expr2} & B"
        if expr1 == f"{expr2} | (~{expr2} & B)":
            return f"{expr2} | B"
        if expr1 == f"({expr2} | B) & ~{expr2}":
            return f"{expr2} | B"
        return expr1

    new_args = args[:]
    for expr1, expr2 in combinations(args, 2):
        new_expr1 = apply_absorption(expr1, expr2)
        new_expr2 = apply_absorption(expr2, expr1)
        if new_expr1 != expr1 or new_expr2 != expr2:
            new_args.remove(expr1)
            new_args.remove(expr2)
            if new_expr1 != expr1:
                new_args.append(new_expr1)
            if new_expr2 != expr2:
                new_args.append(new_expr2)
            return self.absorb(new_args)  # Recursively apply absorption

    return new_args
